const body = $('Webhook: get-current-date').first().json.body;

// Support both Vapi tool-call format and plain/manual testing (curl) calls
const toolCall = body?.message?.toolCalls?.[0];
const toolCallId = toolCall ? toolCall.id : 'manual-test';

const now = new Date();

// Convert to Pakistan Standard Time (UTC+5)
const pkTime = new Date(now.getTime() + (5 * 60 * 60 * 1000));

const dateStr = pkTime.toISOString().split('T')[0];
const timeStr = pkTime.toISOString().split('T')[1].slice(0, 5);
const dayName = pkTime.toLocaleDateString('en-US', { weekday: 'long', timeZone: 'UTC' });
const monthName = pkTime.toLocaleDateString('en-US', { month: 'long', timeZone: 'UTC' });
const dayNum = pkTime.getUTCDate();
const year = pkTime.getUTCFullYear();

const friendly = `Today is ${dayName}, ${monthName} ${dayNum}, ${year}. The current time is ${timeStr} Pakistan Standard Time.`;

return [{
  json: {
    results: [
      {
        toolCallId: toolCallId,
        result: friendly
      }
    ],
    date: dateStr,
    time: timeStr,
    day_of_week: dayName,
    timezone: 'Asia/Karachi'
  }
}];
